// Deterministic SYNTHETIC educational dataset generator.
// The values are random numbers produced in the browser. Feature names are
// deliberately artificial (SYN_GENE_###) so they cannot be mistaken for real
// genes, and the label values are not derived from any real patient.

import { createRng, normal } from './random';

export interface SyntheticOptions {
  seed?: number;
  positives?: number;
  negatives?: number;
  genes?: number;
  informative?: number;
  effectSize?: number;
  missingRate?: number;
}

export const SYNTHETIC_HEADER_NOTE =
  '# SYNTHETIC EDUCATIONAL DATA generated by BioAI.Lab - random numbers, NOT real patient, tumour, or research data';

export function generateSyntheticExpressionCsv(opts: SyntheticOptions = {}): string {
  const seed = opts.seed ?? 2026;
  const nPos = opts.positives ?? 36;
  const nNeg = opts.negatives ?? 30;
  const nGenes = opts.genes ?? 120;
  const nInf = Math.min(opts.informative ?? 8, nGenes);
  const effect = opts.effectSize ?? 0.7;
  const missingRate = opts.missingRate ?? 0.01;
  const rng = createRng(seed);

  const geneNames = Array.from({ length: nGenes }, (_, i) => `SYN_GENE_${String(i + 1).padStart(3, '0')}`);
  const baseMu = geneNames.map(() => 3 + 2 * rng());
  // First half of the informative genes go up in the "tumor" class, second half go down.
  const shift = geneNames.map((_, g) => (g < nInf ? (g < nInf / 2 ? effect : -effect) : 0));

  const lines: string[] = [SYNTHETIC_HEADER_NOTE, ['sample_id', 'condition', 'batch', ...geneNames].join(',')];
  // Interleave classes deterministically so the file is not sorted by label.
  const labels: string[] = [];
  for (let i = 0; i < nPos; i++) labels.push('tumor');
  for (let i = 0; i < nNeg; i++) labels.push('control');
  for (let i = labels.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [labels[i], labels[j]] = [labels[j], labels[i]];
  }
  labels.forEach((label, s) => {
    const batch = rng() < 0.5 ? 'B1' : 'B2';
    const values = geneNames.map((_, g) => {
      if (rng() < missingRate) return 'NA';
      const mu = baseMu[g] + (label === 'tumor' ? shift[g] : 0);
      // log-normal-ish positive expression values (e.g. normalized intensities)
      const v = Math.pow(2, mu + 0.6 * normal(rng));
      return v.toFixed(3);
    });
    lines.push([`SYN_S${String(s + 1).padStart(3, '0')}`, label, batch, ...values].join(','));
  });
  return lines.join('\n') + '\n';
}
